let db,state,day=iso(),page='today',healthState={status:'idle'},planTab=0,saveQueue=Promise.resolve(),storageFailed=false,timerEnd=0,timerInterval,toastTimeout,installPrompt;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function showModal(html){$('#modal-content').innerHTML=html;$('#modal').showModal()}
$('#close-modal').onclick=()=>$('#modal').close();
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('steady-local',1);r.onupgradeneeded=()=>r.result.createObjectStore('data');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function readDB(){return new Promise((resolve,reject)=>{const r=db.transaction('data').objectStore('data').get('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function save(){
 const snapshot=structuredClone(state);
 const current=saveQueue.catch(()=>{}).then(()=>new Promise((resolve,reject)=>{const t=db.transaction('data','readwrite');t.objectStore('data').put(snapshot,'state');t.oncomplete=()=>{storageFailed=false;$('.save-state')?.replaceChildren(document.createTextNode('Saved on device'));$('#storage-error')?.remove();resolve()};t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error||Error('Storage write interrupted'))}));
 saveQueue=current;
 return current.catch(e=>{storageFailed=true;if(!$('#storage-error'))$('#main').insertAdjacentHTML('afterbegin','<p id="storage-error" class="error-box">Could not save on this device. Export a backup now and check available storage. Recent changes may be lost on closing.</p>');toast('Save failed. Please export a backup.');throw e});
}
