function bindDate(){const input=$('#log-date');if(input)input.onchange=()=>{if(!input.value||input.value>iso())return;day=input.value;render()}}
function render(){
 page=location.hash.slice(1)||'today';if(!['today','workout','progress','settings','food','plan'].includes(page))page='today';
 $('#nav').innerHTML=[['today','home','Today'],['workout','lift','Workout'],['progress','chart','Progress'],['settings','settings','Settings']].map(([id,im,label])=>`<a href="#${id}" ${page===id||page==='food'&&id==='today'?'class="active" aria-current="page"':''}>${icon(im)}${label}</a>`).join('');
 ({today:renderToday,workout:renderWorkout,progress:renderProgress,settings:renderSettings,food:renderFood,plan:renderPlan}[page])();bindDate();
 if(storageFailed)$('#main').insertAdjacentHTML('afterbegin','<p id="storage-error" class="error-box">Device storage could not save your latest changes. Export a backup in Settings.</p>');
}
function weekStrip(){const monday=weekStart(day);return `<div class="week-strip">${Array.from({length:7},(_,i)=>{const d=addDays(monday,i),done=state.workouts[d]?.completed,planned=d>=state.settings.start&&d<=state.settings.end&&state.settings.days.includes(dateObj(d).getDay());return `<div class="day ${done?'done':planned?'planned':''} ${d===day?'current':''}">${DAYS[dateObj(d).getDay()]}<span aria-label="${nice(d)} ${done?'completed':planned?'planned':'rest'}">${done?'✓':dateObj(d).getDate()}</span></div>`}).join('')}</div>`}
function renderToday(){
 const l=log(),s=state.settings,w=state.workouts[day],planned=s.days.includes(dateObj(day).getDay()),n=session(),week=programWeek(day,s.start),start=Date.parse(s.start),end=Date.parse(s.end),fraction=Math.max(0,Math.min(100,(Date.parse(day)-start)/(end-start)*100));
 const weights=Object.entries(state.logs).filter(([d,l])=>d<=day&&l.weight).sort((a,b)=>a[0].localeCompare(b[0]));const recent=weights.at(-1);
 $('#main').innerHTML=pageHead(day===iso()?(s.name?'Hello '+esc(s.name)+'.':'Hello.'):'Your daily log.',nice(day,{weekday:'long',month:'long',day:'numeric'}))+`
 <div class="today-layout"><section class="hero"><div class="hero-top"><div><p class="eyebrow">${w?.completed?'Session complete':planned?'Your next session':'Rest day · next session'}</p><h2>${esc(w?workoutPlan(w).name:planFor(n).name)}</h2><p>${w?.completed?'Good work. Eat well, recover, and keep showing up.':planFor(n).subtitle}</p></div><div class="hero-number" aria-hidden="true">${['A','B','C'][n]}</div></div><div><a class="primary" href="#workout">${w?.completed?'Review workout':w?'Continue workout':'Open workout'} ${icon('arrow')}</a><p class="note" style="margin:15px 0 0;color:inherit;opacity:.7">${week<=2?'Ease-in phase · 2 sets maximum per exercise':'Build phase · chest & arms priority'} · 3 days / week · ~45 min</p></div></section>
 <section class="card"><div class="card-head"><h3>This week</h3><span class="pill">${weekWorkouts()} / 3 sessions</span></div>${weekStrip()}<p class="note">${s.days.map(d=>DAYS[d]).join(' · ')} at ${s.time}. Miss a day? Train when you can; your next session stays ready.</p><a class="text-button" href="#settings">Edit your schedule ${icon('arrow')}</a></section></div>
 <div class="section-heading"><h2>The daily check-in</h2><span class="eyebrow" style="margin:0">Keep it simple</span></div><div class="grid2"><section class="card"><div class="card-head"><h3>Nutrition</h3><a class="text-button" href="#food">${l.nutritionSaved?'Edit totals':'Log totals'} ${icon('arrow')}</a></div><div class="metric-number">${l.nutritionSaved?l.calories.toLocaleString():'—'}<small>/ ${s.calories.toLocaleString()} kcal</small></div><div class="progress-track"><span style="width:${Math.min(100,(l.calories||0)/(s.calories||1)*100)}%"></span></div><div class="macro-grid">${[['Protein','protein'],['Carbs','carbs'],['Fat','fat']].map(([label,key])=>`<div><small>${label}</small><b>${l.nutritionSaved?l[key]:'—'}<small style="display:inline;text-transform:none"> g</small></b><small>guide ${s[key]} g</small></div>`).join('')}</div><small>Copy your daily totals from MyFitnessPal.</small></section>
 <section class="card"><div class="card-head"><h3>Your progress</h3><a class="text-button" href="#progress">Check in ${icon('arrow')}</a></div><div class="metric-number">${recent?recent[1].weight:'—'}<small>kg${recent?' · '+nice(recent[0]):''}</small></div>${chart(weights.slice(-14).map(([d,l])=>[d,l.weight]),'Body weight')}<small>Watch the trend, alongside strength and waist.</small></section></div>
 ${stepsCard()}<section class="section-heading"><h2>Building through January.</h2><small>${Math.round(fraction)}%</small></section><div class="progress-track"><span style="width:${fraction}%"></span></div><p class="note">${nice(s.start,{month:'short',day:'numeric',year:'numeric'})} → ${nice(s.end,{month:'short',day:'numeric',year:'numeric'})} · More muscle, consistent training, enough food.</p><p class="footer-note">Small sessions. Honest logs. Steady progress.</p>`;bindSteps();
}
function renderFood(){const l=log();$('#main').innerHTML=`<div class="narrow">${pageHead('Close out your day.','Nutrition')}<section class="card"><div class="card-head"><h2>MyFitnessPal totals</h2><span class="pill">Manual entry</span></div><p class="note">Enter what you ate, even if it differs from your targets. These are daily totals, not individual meals.</p><form id="food-form"><div class="form-grid">${[['Calories','calories','kcal',100000],['Protein','protein','g',10000],['Carbs','carbs','g',10000],['Fat','fat','g',10000]].map(([label,key,unit,max])=>`<label>${label} (${unit})<input name="${key}" type="number" inputmode="decimal" min="0" max="${max}" step="any" required placeholder="${state.settings[key]} guide" value="${l.nutritionSaved?l[key]:''}"></label>`).join('')}</div><div class="form-actions"><button class="primary" type="submit">Save daily totals ${icon('check')}</button><a class="secondary" href="#today">Back</a></div></form><p class="note" style="margin:18px 0 0">Your ${state.settings.calories} kcal target is a starting estimate, not a ceiling. Review energy, weight trend and gym performance before changing it.</p></section></div>`;
 $('#food-form').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.target),entry={...log(),nutritionSaved:true};for(const k of ['calories','protein','carbs','fat'])entry[k]=Number(data.get(k));state.logs[day]=entry;try{await save();toast('Daily totals saved');location.hash='today'}catch{}};
}
function ensureWorkout(){if(state.workouts[day])return state.workouts[day];const n=session(),p=planFor(n);return state.workouts[day]={date:day,session:n,name:p.name,plan:structuredClone(p.exercises),completed:false,exercises:Object.fromEntries(p.exercises.map(e=>[e.id,Array.from({length:setCount(e,day,state.settings)},()=>({kg:'',reps:'',done:false}))]))}}
function renderWorkout(){
 const existing=state.workouts[day],n=session(),plan=existing?workoutPlan(existing):planFor(n),early=programWeek(day,state.settings.start)<=2;
 $('#main').innerHTML=`<div class="workout-list">${pageHead('Show up. Build up.','Your workout')}<div class="workout-toolbar"><label style="flex:1">Session<select id="session-choice" aria-label="Workout session">${[0,1,2].map(i=>{const p=planFor(i);return `<option value="${i}" ${i===n?'selected':''}>${['A','B','C'][i]} · ${p.name}</option>`}).join('')}</select></label><span class="save-state">${existing?'Saved on device':'Ready when you are'}</span></div><a class="text-button" href="#plan">View & edit exercise plan ${icon('arrow')}</a><p class="note" style="margin-top:0">About 45 minutes including warm-up. Chest first; pair curls and triceps when practical. If time runs out, skip the final accessory rather than rushing your main lifts.</p><div class="inline-note"><strong>${early?'First two weeks: ease in.':'Progress one rep at a time.'}</strong> ${early?'Leave 3 good reps in reserve.':'Leave about 2 good reps in reserve.'} Warm up first, including lighter practice sets. Rest about 2 minutes; longer when needed.</div><div class="timer-bar"><div><small>Rest timer</small><div id="timer" class="timer-display">2:00</div></div><div class="segmented"><button data-timer="90">90s</button><button data-timer="120">2m</button><button data-timer="180">3m</button></div><button class="secondary" id="stop-timer" aria-label="Stop rest timer">Stop</button></div>
 ${plan.exercises.map((e,i)=>{const last=lastExercise(state.workouts,e.id,day),rows=existing?.exercises[e.id]||Array.from({length:setCount(e,day,state.settings)},()=>({kg:'',reps:'',done:false}));return `<section class="exercise"><div class="exercise-head"><span class="exercise-index">${String(i+1).padStart(2,'0')}</span><div class="exercise-title"><h3>${esc(e.name)}</h3><small>${e.reps} reps · ${rows.length} ${rows.length===1?'set':'sets'}</small></div><span class="exercise-tag">${e.group}</span></div><div class="sets"><p class="note" style="margin:0 0 10px">${esc(e.cue)}</p><p class="note" style="color:var(--accent);margin:0 0 12px">Last time: ${last.length?last.map(r=>`${r.kg} kg × ${r.reps}`).join(' · '):'Your first entry. Start comfortably.'}</p><div class="set-row labels"><span>Set</span><span>kg</span><span>Reps</span><span>Done</span></div>${rows.map((r,j)=>`<div class="set-row ${r.done?'completed':''}" data-ex="${e.id}" data-row="${j}"><span>${j+1}</span><input aria-label="${esc(e.name)} set ${j+1} weight in kg" type="number" inputmode="decimal" min="0" max="2000" step="any" data-key="kg" value="${r.kg}" placeholder="${last[j]?.kg??'—'}"><input aria-label="${esc(e.name)} set ${j+1} reps" type="number" inputmode="numeric" min="1" max="100" step="1" data-key="reps" value="${r.reps}" placeholder="${last[j]?.reps??e.reps}"><button class="check-set ${r.done?'checked':''}" aria-pressed="${r.done}" aria-label="Mark ${esc(e.name)} set ${j+1} ${r.done?'incomplete':'complete'}">${icon('check')}</button></div>`).join('')}</div></section>`}).join('')}
 <section class="card" style="margin:18px 0"><h3>Neck · gentle 2-minute finisher</h3><p class="note">Keep your neck neutral. Press your hand gently against your forehead, then the back and each side of your head, resisting without moving. Hold 5 seconds each, breathing normally. One easy round to start; up to two if comfortable. No weights or neck bridges. Stop if you feel pain, dizziness, tingling or a headache.</p><label style="display:flex;gap:12px;align-items:center"><input id="neck-done" type="checkbox" ${existing?.neckDone?'checked':''}> Gentle neck routine completed (optional)</label></section>
 <button class="${existing?.completed?'secondary':'primary'} full" id="finish-workout">${existing?.completed?'Workout complete · reopen to edit':'Finish workout'} ${icon('check')}</button><p class="note">Only checked sets count as completed. When every set reaches the top of the rep range with controlled technique, add the smallest weight increment next time. Dumbbells: log one dumbbell. Machines: use the same machine for fair comparisons.</p><button class="text-button" id="discard-workout">${existing?.completed?'Delete this workout':'Discard today’s draft'}</button></div>`;
 $('#neck-done').onchange=()=>{ensureWorkout().neckDone=$('#neck-done').checked;persist()};
 $('#session-choice').onchange=async e=>{const old=state.workouts[day];if(old&&Object.values(old.exercises).flat().some(r=>r.kg!==''||r.reps!==''||r.done)&&!confirm('Switch sessions? This replaces the workout entries for this date.')){e.target.value=n;return}const chosen=Number(e.target.value);state.workouts[day]={date:day,session:chosen,name:planFor(chosen).name,plan:structuredClone(planFor(chosen).exercises),completed:false,exercises:Object.fromEntries(planFor(chosen).exercises.map(e=>[e.id,Array.from({length:setCount(e,day,state.settings)},()=>({kg:'',reps:'',done:false}))]))};await persist();renderWorkout()};
 $$('.set-row input').forEach(input=>input.oninput=()=>{const row=input.closest('[data-ex]'),w=ensureWorkout(),r=w.exercises[row.dataset.ex][Number(row.dataset.row)];r[input.dataset.key]=input.value===''||!input.checkValidity()?'':Number(input.value);if(r.done){r.done=false;row.classList.remove('completed');const b=row.querySelector('button');b.classList.remove('checked');b.setAttribute('aria-pressed','false')}w.completed=false;$('#finish-workout').textContent='Finish workout';$('.save-state').textContent='Saving…';persist()});
 $$('.check-set').forEach(b=>b.onclick=async()=>{const row=b.closest('[data-ex]'),inputs=[...row.querySelectorAll('input')];if(inputs.some(i=>i.value===''||!i.checkValidity())){inputs.find(i=>i.value===''||!i.checkValidity())?.focus();toast('Enter a valid weight and reps first');return}const w=ensureWorkout(),r=w.exercises[row.dataset.ex][Number(row.dataset.row)];r.done=!r.done;w.completed=false;b.classList.toggle('checked',r.done);b.setAttribute('aria-pressed',r.done);b.setAttribute('aria-label',`Mark ${workoutPlan(w).exercises.find(e=>e.id===row.dataset.ex).name} set ${Number(row.dataset.row)+1} ${r.done?'incomplete':'complete'}`);row.classList.toggle('completed',r.done);$('#finish-workout').textContent='Finish workout';await persist()});
 $('#finish-workout').onclick=async()=>{const w=state.workouts[day];if(w?.completed){w.completed=false;await persist();renderWorkout();return}if(!w||!Object.values(w.exercises).flat().some(r=>r.done)){toast('Complete at least one set before finishing');return}const rows=Object.values(w.exercises).flat(),done=rows.filter(r=>r.done).length;if(done<rows.length&&!confirm(`You checked ${done} of ${rows.length} ${rows.length===1?'set':'sets'}. Finish with the remaining sets skipped?`))return;w.completed=true;try{await save();stopTimer();toast('Workout saved. Good work.');location.hash='today'}catch{}};
 $('#discard-workout').onclick=async()=>{if(!state.workouts[day])return;if(!confirm('Delete this workout and its sets?'))return;delete state.workouts[day];await persist();renderWorkout()};
 $$('[data-timer]').forEach(b=>b.onclick=()=>startTimer(Number(b.dataset.timer)));$('#stop-timer').onclick=stopTimer;updateTimer();
}
function updateTimer(){const left=timerEnd?Math.max(0,Math.ceil((timerEnd-Date.now())/1000)):120;const el=$('#timer');if(el)el.textContent=`${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`;if(timerEnd&&left===0){timerEnd=0;clearInterval(timerInterval);toast('Rest done. Ready for your next set?');navigator.vibrate?.([100,50,100])}}
function startTimer(seconds){timerEnd=Date.now()+seconds*1000;clearInterval(timerInterval);timerInterval=setInterval(updateTimer,250);updateTimer()}
function stopTimer(){timerEnd=0;clearInterval(timerInterval);updateTimer()}
function chart(entries,label){if(!entries.length)return `<div class="empty">Your ${label.toLowerCase()} trend starts with your first check-in.</div>`;const points=chartPoints(entries);return `<svg class="chart" viewBox="0 0 300 130" role="img" aria-label="${label}: ${entries.map(e=>`${nice(e[0])}: ${e[1]}`).join(', ')}"><line x1="10" y1="100" x2="290" y2="100"/><polyline points="${points.map(p=>`${p.x},${p.y}`).join(' ')}"/>${points.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="3.5"><title>${nice(p.date)}: ${p.value}</title></circle>`).join('')}<text x="10" y="123">${nice(entries[0][0])}</text><text x="290" y="123" text-anchor="end">${nice(entries.at(-1)[0])}</text></svg>`}
function renderProgress(){
 const entries=Object.entries(state.logs).filter(([d])=>d<=day).sort((a,b)=>a[0].localeCompare(b[0])),weights=entries.filter(([,l])=>l.weight).map(([d,l])=>[d,l.weight]),waists=entries.filter(([,l])=>l.waist).map(([d,l])=>[d,l.waist]),lastWeek=weights.filter(([d])=>d>=addDays(day,-6)),avg=lastWeek.length?(lastWeek.reduce((s,[,n])=>s+n,0)/lastWeek.length).toFixed(1):'—';
 $('#main').innerHTML=pageHead('See the bigger picture.','Your progress')+`<div class="stat-strip"><div><strong>${avg}<small> kg</small></strong><small>7-DAY WEIGHT AVERAGE</small></div><div><strong>${completed().filter(w=>w.date<=day).length}</strong><small>SESSIONS COMPLETED</small></div><div><strong>${waists.at(-1)?.[1]??'—'}<small> cm</small></strong><small>LATEST WAIST</small></div></div><div class="grid2"><section class="card"><h3>Body weight</h3>${chart(weights.slice(-30),'Body weight')}<small>Similar conditions each time. Trends matter more than a single reading.</small></section><section class="card"><h3>Waist</h3>${chart(waists.slice(-16),'Waist')}<small>Once a week, around your navel, relaxed, after a normal breath out.</small></section></div>
 <div class="section-heading"><h2>Check in</h2><small>${nice(day)}</small></div><section class="card"><form id="measure-form"><div class="form-grid"><label>Body weight (kg)<input type="number" name="weight" min="20" max="500" step="0.1" inputmode="decimal" value="${log().weight??''}" placeholder="e.g. 78.0"></label><label>Waist (cm) · weekly<input type="number" name="waist" min="30" max="300" step="0.1" inputmode="decimal" value="${log().waist??''}" placeholder="e.g. 88.0"></label></div><div class="form-actions"><button class="primary" type="submit">Save measurements</button></div><p class="note" style="margin-bottom:0">Leave a field blank to remove that measurement for this date.</p></form></section>
 <div class="section-heading"><h2>Progress photos</h2><span class="pill">Device only</span></div><section class="card"><p class="note">Same light, distance, and pose every 2 weeks. Photos are stored in this browser and included in backups.</p><form id="photo-form"><div class="form-grid"><label>View<select name="view"><option>Front</option><option>Side</option><option>Back</option></select></label><label>Choose photo<input type="file" name="photo" accept="image/jpeg,image/png,image/webp" required></label></div><div class="form-actions"><button class="secondary" type="submit">${icon('plus')} Add photo</button></div></form><div class="photo-grid">${state.photos.filter(p=>p.date<=day).sort((a,b)=>b.date.localeCompare(a.date)).map(p=>`<figure><button style="padding:0;background:none;width:100%" data-open-photo="${esc(p.id)}" aria-label="View ${p.view} photo from ${nice(p.date)}"><img src="${p.src}" alt="${p.view} progress photo from ${nice(p.date)}" loading="lazy"></button><figcaption>${nice(p.date)} · ${p.view}</figcaption><button class="text-button" data-delete-photo="${esc(p.id)}">Delete</button></figure>`).join('')}</div>${!state.photos.length?'<div class="empty">Your first photo is a starting point, not a judgement.</div>':''}</section>
 <div class="section-heading"><h2>Recent logs</h2></div><section class="card">${entries.length?entries.slice(-10).reverse().map(([d,l])=>`<div class="history-row"><div><h3>${nice(d)}</h3><small>${[l.weight?l.weight+' kg':null,l.waist?l.waist+' cm waist':null,l.nutritionSaved?l.calories+' kcal':null].filter(Boolean).join(' · ')||'No measurements'}</small></div><button class="text-button" data-edit-date="${d}">Edit</button></div>`).join(''):'<p class="note">Your check-ins will appear here.</p>'}</section><div class="section-heading"><h2>Workout history</h2></div><section class="card">${completed().filter(w=>w.date<=day).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,12).map(w=>`<div class="history-row"><div><h3>${esc(w.name||PLAN[w.session].name)}</h3><small>${nice(w.date)} · ${Object.values(w.exercises).flat().filter(r=>r.done).length} sets</small></div><button class="text-button" data-workout-date="${w.date}">Review</button></div>`).join('')||'<p class="note">Finish your first session to start your history.</p>'}</section>`;
 $('#measure-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),entry={...log()};for(const key of ['weight','waist']){if(f.get(key)==='')delete entry[key];else entry[key]=Number(f.get(key))}state.logs[day]=entry;try{await save();toast('Measurements saved');renderProgress();bindDate()}catch{}};
 $('#photo-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),file=f.get('photo'),button=e.target.querySelector('button');if(file.size>25*1024*1024){toast('Choose a photo smaller than 25 MB');return}button.disabled=true;button.textContent='Saving photo…';try{const src=await resizeImage(file);state.photos.push({id:crypto.randomUUID(),date:day,view:f.get('view'),src});await save();toast('Photo saved on this device');renderProgress();bindDate()}catch(err){toast('Photo could not be saved. Check file format and storage.');button.disabled=false;button.textContent='Add photo'}};
 $$('[data-delete-photo]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this photo from this device?'))return;state.photos=state.photos.filter(p=>p.id!==b.dataset.deletePhoto);await persist();renderProgress();bindDate()});
 $$('[data-open-photo]').forEach(b=>b.onclick=()=>{const p=state.photos.find(p=>p.id===b.dataset.openPhoto);showModal(`<h2>${p.view} · ${nice(p.date)}</h2><img src="${p.src}" alt="${p.view} progress photo">`)});
 $$('[data-edit-date]').forEach(b=>b.onclick=()=>{day=b.dataset.editDate;renderProgress();bindDate();$('#measure-form').scrollIntoView({block:'center'})});
 $$('[data-workout-date]').forEach(b=>b.onclick=()=>{day=b.dataset.workoutDate;location.hash='workout'});
}
async function resizeImage(file){const bitmap=await createImageBitmap(file),scale=Math.min(1,1400/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return canvas.toDataURL('image/jpeg',.82)}
function renderSettings(){const s=state.settings;
 $('#main').innerHTML=`<div class="narrow">${pageHead('Settings.','Your log',false)}<div class="settings-stack"><section class="card"><h2>What should we call you?</h2><form id="name-form"><label>Name (optional)<input name="name" type="text" autocomplete="off" maxlength="40" value="${esc(s.name||'')}" placeholder="Your name"></label><p class="note">Only used for your hello on the home screen. Saved on this device.</p><button type="submit" class="primary">Save name</button></form></section><section class="card"><h2>Your week</h2><form id="schedule-form"><label>Choose exactly 3 gym days</label><div class="check-days">${[1,2,3,4,5,6,0].map(d=>`<label><input type="checkbox" name="days" value="${d}" ${s.days.includes(d)?'checked':''}><span>${DAYS[d]}</span></label>`).join('')}</div><div class="form-grid"><label>Workout time<input name="time" type="time" value="${s.time}" required></label><label>Program starts<input name="start" type="date" value="${s.start}" required></label><label>Goal date<input name="end" type="date" value="${s.end}" required></label></div><p class="note">Keep a rest day between sessions where possible. A → B → C follows completed sessions, so moving a day won't lose your place.</p><button class="primary" type="submit">Save schedule</button></form></section>
 <section class="card"><h2>Workout reminders</h2><p class="note">Add each saved gym day to Google Calendar. Choose your notification time in Calendar before tapping Save; Calendar handles reminders when Steady is closed.</p><div class="calendar-links">${s.days.map(d=>{const event=calendarEvent(s,d,window.SteadyAndroid?'':location.href.split('#')[0]);return event?`<a class="secondary" href="${esc(event.url)}" target="_blank" rel="noopener noreferrer">Add ${DAYS[d]} ${icon('plus')}</a>`:''}).join('')||'<p class="note">No upcoming workout days before your goal date. Edit your schedule above.</p>'}</div><button class="text-button" id="calendar-download">Download calendar file (.ics)</button><p class="note">Schedule changes here do not update events already added to Calendar. Delete the old repeating events there, then add the new schedule here. Calendar file imports may need a desktop browser; the buttons above are best for Android.</p></section>
 <section class="card"><h2>Daily nutrition guides</h2><form id="targets-form"><div class="form-grid">${[['Calories (kcal)','calories'],['Protein (g)','protein'],['Carbs (g)','carbs'],['Fat (g)','fat']].map(([name,key])=>`<label>${name}<input name="${key}" type="number" min="0" max="10000" step="1" inputmode="numeric" value="${s[key]}" required></label>`).join('')}</div><p class="note">Starting estimates, not a strict limit. Aim around maintenance while rebuilding strength. Carbs and fats are flexible guides; totals may differ slightly due to rounding.</p><button class="primary" type="submit">Save guides</button></form></section>
 <section class="card"><h2>Your training approach</h2><a class="text-button" href="#plan">View & edit exercises ${icon('arrow')}</a><p class="note">About 45 minutes, 3 days per week. Default sessions prioritise chest, biceps, triceps and forearms, with back and lower-body work retained. Chest gets 10 working sets and biceps/triceps get 6 direct sets each per A/B/C cycle after the ease-in phase. Presses also train triceps. A gentle neck routine is optional. Your exercise plan is editable.</p><ul class="detail-list"><li>Start light enough to leave 3 good reps in reserve. After the ease-in phase, generally leave about 2.</li><li>Add reps first. When every set reaches the top of the range, use the smallest available weight increase.</li><li>Rest about 2 minutes, longer if needed. Lifting heavier every visit isn't required.</li><li>Warm up before working sets. Stop movements that cause pain; ask gym staff to help with unfamiliar machines.</li><li>Use the same machine, setup and technique so your logs are comparable. Dumbbell entries are per dumbbell.</li></ul><p class="note">Starting information: 21, male, 177 cm, approximately 78 kg. No target weight required. Training volume reference: <a href="https://acsm.org/resistance-training-guidelines-update-2026/" target="_blank" rel="noopener noreferrer">ACSM guidance</a>.</p></section>
 <section class="card"><h2>Samsung Health steps</h2><p class="note">Automatic steps need the installed Android app. In Samsung Health, open Settings → Health Connect → App permissions, and allow Samsung Health to write Steps. In Steady, tap Connect / refresh on Today and allow read-only Steps access. Open Samsung Health once after changing sharing settings.</p><p class="note">Refresh happens when Steady opens or you tap Refresh. Counts can lag while Samsung Health syncs. Only Samsung Health records are read, rather than adding phone and watch totals twice. No background, heart-rate or location permission is requested. The Android app and Chrome have separate storage; export/restore a backup to move your log.</p><p class="note"><a href="https://developer.samsung.com/health/health-connect-faq.html" target="_blank" rel="noopener noreferrer">Samsung setup reference</a> · <a href="https://developer.android.com/health-and-fitness/health-connect/features/steps" target="_blank" rel="noopener noreferrer">Health Connect steps</a></p></section><section class="card"><h2>${window.SteadyAndroid?'Android app installed':'On your Android'}</h2><p class="note">${window.SteadyAndroid?'You are using the installed app. Its screens and logs work offline. Steps refresh from Health Connect when the app is open.':'For the web version, open Steady in Chrome and use ⋮ → Add to Home screen. Automatic Samsung Health steps require the separate Android APK.'}</p><button class="secondary" id="install-app" ${window.SteadyAndroid?'hidden':''}>${installPrompt?'Install Steady':'Show installation steps'}</button><p class="note">Your logs and photos stay in this browser. Clearing site data, private browsing, or switching browsers can lose access to them. Export backups regularly, including before changing phones. The Android app bundles its screens for offline use; the browser version caches them after its first successful load.</p></section>
 <section class="card"><h2>Your data</h2><p class="note">A backup includes your schedule, targets, workout sets, daily totals, measurements and photos. Keep the downloaded file somewhere private.</p><button class="primary full" id="export-backup">Export full backup</button><form id="import-form" style="margin-top:20px"><label>Restore a Steady backup (.json)<input type="file" name="backup" accept="application/json,.json" required></label><button class="secondary full" style="margin-top:12px" type="submit">Restore backup</button></form><p class="note">Restore replaces the data on this device. Export your current data first if you want to keep it.</p></section></div><p class="footer-note">Steady v1.2 · Built for consistency.</p></div>`;
 $('#name-form').onsubmit=async e=>{e.preventDefault();s.name=normalizeName(new FormData(e.target).get('name'));try{await save();toast('Name saved');renderSettings()}catch{}};
 $('#schedule-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),days=f.getAll('days').map(Number);if(days.length!==3){toast('Choose exactly 3 gym days');return}if(f.get('start')>=f.get('end')){toast('Goal date must be after the start date');return}Object.assign(s,{days,time:f.get('time'),start:f.get('start'),end:f.get('end')});try{await save();toast('Schedule saved. Update Calendar reminders if needed.');renderSettings()}catch{}};
 $('#targets-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);for(const k of ['calories','protein','carbs','fat'])s[k]=Number(f.get(k));try{await save();toast('Nutrition guides saved')}catch{}};
 $('#export-backup').onclick=()=>download(`steady-backup-${iso()}.json`,JSON.stringify(state,null,2),'application/json');
 $('#import-form').onsubmit=async e=>{e.preventDefault();const file=new FormData(e.target).get('backup');if(file.size>150*1024*1024){toast('Backup is too large (maximum 150 MB)');return}let clean;try{clean=validateBackup(JSON.parse(await file.text()))}catch(err){toast(err.message||'This backup could not be read');return}if(!confirm('Replace all current logs and photos with this backup? Export your current data first if you want to keep it.'))return;state=clean;try{await save();theme();toast('Backup restored');renderSettings()}catch{}};
 $('#calendar-download').onclick=downloadCalendar;
 $('#install-app').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;renderSettings()}else showModal('<h2>Add Steady to your home screen</h2><ol class="detail-list"><li>Open this address in Chrome on your Android phone.</li><li>Tap the three-dot menu in the top-right corner.</li><li>Choose <strong>Add to Home screen</strong>, then <strong>Install</strong> or <strong>Create shortcut</strong>.</li><li>Open Steady from its new icon.</li></ol><p class="note">If you see a sign-in screen, use the same ChatGPT account that owns this private app.</p>')};
}
function download(name,text,type){if(window.SteadyAndroid){window.SteadyAndroid.saveFile(name,text,type);return}const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('Download requested')}
function downloadCalendar(){const s=state.settings,lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Steady//Gym schedule//EN','CALSCALE:GREGORIAN'];let count=0;for(const weekday of s.days){const event=calendarEvent(s,weekday);if(!event)continue;count++;lines.push('BEGIN:VEVENT',`UID:${crypto.randomUUID()}@steady.local`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}`,`DTSTART:${event.start}`,`DTEND:${event.end}`,`RRULE:FREQ=WEEKLY;BYDAY=${['SU','MO','TU','WE','TH','FR','SA'][weekday]};UNTIL=${s.end.replaceAll('-','')}T235959`,'SUMMARY:Steady - Gym','DESCRIPTION:Open Steady for your next A / B / C workout.','BEGIN:VALARM','TRIGGER:-PT30M','ACTION:DISPLAY','DESCRIPTION:Your Steady gym session starts in 30 minutes.','END:VALARM','END:VEVENT')}if(!count){toast('No upcoming workouts before the goal date');return}lines.push('END:VCALENDAR');download('steady-workouts.ics',lines.join('\r\n')+'\r\n','text/calendar')}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
async function init(){try{db=await openDB();state=await readDB()||{version:1,settings:{...DEFAULTS},logs:{},workouts:{},photos:[]};state.settings.name=normalizeName(state.settings.name);state.plans??=structuredClone(PLAN);for(const w of Object.values(state.workouts)){if(!w.plan){w.plan=structuredClone(LEGACY_PLAN[w.session].exercises);w.name=LEGACY_PLAN[w.session].name}}theme();render();if('serviceWorker' in navigator&&!window.SteadyAndroid)navigator.serviceWorker.register('./sw.js').catch(()=>{})}catch(err){$('#main').innerHTML='<div class="error-box"><h2>Device storage is unavailable.</h2><p>Open Steady in a regular Chrome tab and allow site storage. Your logs need browser storage to be saved safely.</p><button class="secondary" id="retry-init">Try again</button></div>';$('#retry-init').onclick=()=>location.reload()}}



function stepsCard(){const l=log(),native=!!window.SteadyAndroid;return `<section class="card" id="steps-card" style="margin-top:20px"><div class="card-head"><h3>Daily steps</h3><span class="pill">${l.stepsSource?.includes('Samsung')?'Health Connect':native?'Android':'Manual'}</span></div><div class="metric-number">${l.steps!==undefined?l.steps.toLocaleString():'—'}<small>steps</small></div><p class="note">${l.steps!==undefined?esc(l.stepsSource||'Manual entry')+(l.stepsSyncedAt?' · Last synced '+esc(new Date(l.stepsSyncedAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})):''):'Your daily movement, alongside your training.'}</p><p class="note" id="health-status">${native?esc(healthState.message||'Tap Refresh to read this date from Health Connect.'):'Automatic Samsung Health steps are available in the Android app. You can also enter a total below.'}</p>${native?`<div class="form-actions"><button class="primary" id="connect-health">${healthState.status==='connected'?'Refresh steps':'Connect / refresh'}</button><button class="secondary" id="health-settings">Permissions</button></div>`:''}<details style="margin-top:15px"><summary class="note" style="cursor:pointer">${l.steps!==undefined?'Edit or remove saved steps':'Enter steps manually'}</summary><form id="steps-form" style="margin-top:12px"><label>Steps for ${nice(day)}<input name="steps" type="number" inputmode="numeric" min="0" max="100000" step="1" value="${l.steps??''}" placeholder="e.g. 6500"></label><button type="submit" class="secondary" style="margin-top:10px">Save steps</button><p class="note">Blank removes this saved total. A successful Health Connect refresh replaces manual steps for the date.</p></form></details></section>`}
function bindSteps(){const form=$('#steps-form');if(form)form.onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),l={...log()};if(f.get('steps')===''){delete l.steps;delete l.stepsSource;delete l.stepsSyncedAt}else{l.steps=Number(f.get('steps'));l.stepsSource='Manual entry';delete l.stepsSyncedAt}state.logs[day]=l;try{await save();toast('Steps saved');updateStepsCard()}catch{}};const connect=$('#connect-health');if(connect)connect.onclick=()=>{healthState={status:'loading',date:day,message:'Checking Health Connect…'};updateStepsCard();window.SteadyAndroid.connectHealth(day)};const settings=$('#health-settings');if(settings)settings.onclick=()=>window.SteadyAndroid.healthSettings();if(window.SteadyAndroid&&healthState.date!==day){healthState={status:'loading',date:day,message:'Checking Health Connect…'};window.SteadyAndroid.readSteps(day)}}
function updateStepsCard(){const card=$('#steps-card');if(!card)return;card.outerHTML=stepsCard();bindSteps()}
window.addEventListener('steady-health',async e=>{if(!state)return;const d=e.detail;if(!d||typeof d.date!=='string')return;healthState=d;if(d.status==='connected'&&Number.isSafeInteger(d.count)&&d.count>=0&&d.count<=100000){state.logs[d.date]={...state.logs[d.date],steps:d.count,stepsSource:'Samsung Health via Health Connect',stepsSyncedAt:d.syncedAt};await persist()}if(d.date===day)updateStepsCard()});
window.addEventListener('steady-file',e=>toast(e.detail));
function renderPlan(){
 const plans=state.plans||PLAN,p=plans[planTab],minutes=estimatedMinutes(p.exercises);
 $('#main').innerHTML=`<div class="narrow">${pageHead('Your exercises. Your way.','View & edit plan',false)}<p class="note">Preview each session, then adjust it to suit your gym. Changes apply to new workouts. Existing drafts and saved sessions keep their original exercises; discard a draft if you want to start it with the revised plan.</p><div class="session-chips">${plans.map((p,i)=>`<button data-plan-tab="${i}" class="${i===planTab?'selected':''}">Session ${['A','B','C'][i]}</button>`).join('')}</div><section class="card"><div class="card-head"><h2>${esc(p.name)}</h2><span class="pill">~${minutes} min</span></div><p class="note">${p.exercises.reduce((n,e)=>n+e.sets,0)} working sets · estimate includes warm-up and short transitions. Busy equipment and longer rests can add time.</p><form id="plan-form">${p.exercises.map((e,i)=>{const range=e.reps.split(/[–-]/);return `<section class="plan-exercise" data-plan-index="${i}"><label>Exercise ${i+1}<select name="exercise-${i}">${EXERCISES.map(option=>`<option value="${option.id}" ${option.id===e.id?'selected':''}>${esc(option.name)}</option>`).join('')}</select></label><div class="plan-numbers"><label>Sets<input name="sets-${i}" type="number" inputmode="numeric" min="1" max="5" step="1" required value="${e.sets}"></label><label>Min reps<input name="low-${i}" type="number" inputmode="numeric" min="1" max="50" step="1" required value="${range[0]}"></label><label>Max reps<input name="high-${i}" type="number" inputmode="numeric" min="1" max="50" step="1" required value="${range[1]}"></label></div><div class="plan-actions"><button type="button" class="text-button" data-plan-up="${i}" ${i===0?'disabled':''}>↑ Move up</button><button type="button" class="text-button" data-plan-down="${i}" ${i===p.exercises.length-1?'disabled':''}>↓ Move down</button><button type="button" class="text-button" data-plan-remove="${i}" ${p.exercises.length===1?'disabled':''}>Remove</button></div></section>`}).join('')}<div class="form-actions"><button class="primary" type="submit">Save exercise plan</button><button class="secondary" type="button" id="add-exercise" ${p.exercises.length>=10?'disabled':''}>${icon('plus')} Add</button></div></form><p class="note">For your 45-minute goal, keep most sessions around 12–14 working sets. Keep chest first, use curls + triceps as a pair, and retain some back and leg work.</p><a class="text-button" href="#workout">Back to workout ${icon('arrow')}</a></section><section class="card" style="margin-top:18px"><h3>Gentle neck finisher</h3><p class="note">The workout screen includes an optional short, unloaded neck isometric routine. It stays separate from the weight-training sets. Avoid heavy neck loading or copying the cheat sheet's 18+ sets as a starting target.</p><button class="text-button" id="reset-plan">Restore default A/B/C plan</button></section></div>`;
 function readForm(){const f=new FormData($('#plan-form'));return p.exercises.map((_,i)=>{const base=EXERCISES.find(e=>e.id===f.get(`exercise-${i}`));return {...base,sets:Number(f.get(`sets-${i}`)),reps:f.get(`low-${i}`)+'–'+f.get(`high-${i}`)}})}
 async function commitEdits(exercises,notify=true){try{const copy=structuredClone(state.plans||PLAN);copy[planTab].exercises=exercises;const checked=validatePlan(copy);state.plans=checked;await save();if(notify)toast('Plan saved for new workouts');renderPlan();return true}catch(err){toast(err.message||'Plan could not be saved');return false}}
 $('#plan-form').onsubmit=async e=>{e.preventDefault();await commitEdits(readForm())};
 $$('[data-plan-tab]').forEach(b=>b.onclick=()=>{const edits=readForm();if(JSON.stringify(edits)!==JSON.stringify(p.exercises)&&!confirm('Switch sessions without saving these edits?'))return;planTab=Number(b.dataset.planTab);renderPlan()});
 $$('[data-plan-up]').forEach(b=>b.onclick=async()=>{const list=readForm(),i=Number(b.dataset.planUp);[list[i-1],list[i]]=[list[i],list[i-1]];await commitEdits(list,false)});
 $$('[data-plan-down]').forEach(b=>b.onclick=async()=>{const list=readForm(),i=Number(b.dataset.planDown);[list[i+1],list[i]]=[list[i],list[i+1]];await commitEdits(list,false)});
 $$('[data-plan-remove]').forEach(b=>b.onclick=async()=>{const list=readForm();list.splice(Number(b.dataset.planRemove),1);await commitEdits(list,false)});
 $('#add-exercise').onclick=async()=>{const list=readForm(),next=EXERCISES.find(e=>!list.some(item=>item.id===e.id));if(next){list.push({...next,sets:2});await commitEdits(list,false)}};
 $('#reset-plan').onclick=async()=>{if(!confirm('Restore all three default sessions? Saved workouts will be kept.'))return;state.plans=structuredClone(PLAN);await persist();renderPlan()};
}
init();




